import React, { useEffect, useState } from "react";
import { api, fmt } from "../lib/api";
import { useAuth } from "../context/AuthContext";
import { toast } from "sonner";

const INIT = { title: "", description: "", company: "", location: "", job_type: "Full-time", link: "" };

export default function Jobs() {
  const { user } = useAuth();
  const [jobs, setJobs] = useState([]);
  const [form, setForm] = useState(INIT);
  const [showForm, setShowForm] = useState(false);
  const load = async () => { const { data } = await api.get("/opportunities"); setJobs(data); };
  useEffect(() => { load(); }, []);
  const create = async () => {
    try { await api.post("/opportunities", form); toast.success("Posted."); setShowForm(false); setForm(INIT); load(); }
    catch (e) { toast.error(fmt(e.response?.data?.detail)); }
  };
  const remove = async (id) => {
    try { await api.delete(`/opportunities/${id}`); toast.success("Removed."); load(); }
    catch (e) { toast.error(fmt(e.response?.data?.detail)); }
  };
  const canPost = user?.role === "alumni" || user?.role === "admin";
  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: "3rem 2rem" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
        <div>
          <div className="overline">Opportunities</div>
          <h1 className="font-serif" style={{ fontSize: "2.5rem", color: "var(--ivy)", margin: "8px 0" }}>Roles shared by the community.</h1>
        </div>
        {canPost && <button className="btn-accent" onClick={() => setShowForm(!showForm)}>{showForm ? "Cancel" : "+ Post"}</button>}
      </div>
      {showForm && (
        <div className="card-editorial" style={{ padding: 24, marginBottom: 24, display: "grid", gap: 12 }}>
          <input className="input" placeholder="Title" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} />
          <input className="input" placeholder="Company" value={form.company} onChange={e => setForm({ ...form, company: e.target.value })} />
          <input className="input" placeholder="Location" value={form.location} onChange={e => setForm({ ...form, location: e.target.value })} />
          <input className="input" placeholder="Type (Full-time/Internship)" value={form.job_type} onChange={e => setForm({ ...form, job_type: e.target.value })} />
          <input className="input" placeholder="Apply link" value={form.link} onChange={e => setForm({ ...form, link: e.target.value })} />
          <textarea className="input" rows={4} placeholder="Description" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} />
          <button className="btn-primary" onClick={create}>Publish</button>
        </div>
      )}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))", gap: 16 }}>
        {jobs.map(j => (
          <div key={j._id} className="card-editorial" style={{ padding: 24 }}>
            <div className="overline">{j.job_type}</div>
            <h2 className="font-serif" style={{ fontSize: 22, color: "var(--ivy)", margin: "6px 0" }}>{j.title}</h2>
            <div style={{ color: "var(--muted)", fontSize: 14 }}>{j.company} · {j.location || "Remote"}</div>
            <p style={{ color: "var(--muted)", fontSize: 13, lineHeight: 1.6, margin: "12px 0" }}>{j.description}</p>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div style={{ fontSize: 12, color: "var(--muted)" }}>By {j.postedByName}</div>
              <div style={{ display: "flex", gap: 8 }}>
                {j.link && <a href={j.link} target="_blank" rel="noreferrer"><button className="btn-outline">Apply ↗</button></a>}
                {(user?.id === j.postedBy || user?.role === "admin") && <button className="btn-outline" onClick={() => remove(j._id)}>Delete</button>}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
